// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount <= address(actor).balance + 1e30);
        vm.deal(actor, amount);
        uint before = c.depositsCount();
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(ok && c.depositsCount() == before + 1);
    }
}
